-- Seller workspace: lists, notes, follow-ups and estimate requests (seller -> owner -> customer).
CREATE TABLE IF NOT EXISTS client_lists(id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL REFERENCES client_accounts(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS client_list_items(list_id INTEGER NOT NULL REFERENCES client_lists(id) ON DELETE CASCADE,permit_key TEXT NOT NULL,PRIMARY KEY(list_id,permit_key));
CREATE TABLE IF NOT EXISTS client_notes(client_id INTEGER NOT NULL REFERENCES client_accounts(id) ON DELETE CASCADE,permit_key TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,PRIMARY KEY(client_id,permit_key));
CREATE TABLE IF NOT EXISTS followups(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,client_id INTEGER NOT NULL REFERENCES client_accounts(id) ON DELETE CASCADE,permit_key TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',task TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'task',due_at TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',done_at TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS estimate_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,client_id INTEGER NOT NULL REFERENCES client_accounts(id) ON DELETE CASCADE,permit_key TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT '',prospect_name TEXT NOT NULL DEFAULT '',prospect_email TEXT NOT NULL DEFAULT '',scope TEXT NOT NULL DEFAULT '',measurements TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',owner_note TEXT NOT NULL DEFAULT '',seller_feedback TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',total REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sent_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS estimate_events(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL REFERENCES estimate_requests(id) ON DELETE CASCADE,kind TEXT NOT NULL,text TEXT NOT NULL DEFAULT '',by_name TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
PRAGMA user_version=12;
